def add(x, y):
    """Add two numbers."""
    return x + y

def subtract(x, y):
    """Subtract two numbers."""
    return x - y

def multiply(x, y):
    """Multiply two numbers."""
    return x * y

def divide(x, y):
    """Divide two numbers."""
    if y == 0:
        return "Error! Division by zero."
    return x / y

def calculator():
    """Main function to handle user input and display results."""
    print("Select operation:")
    print("1. Add")
    print("2. Subtract")
    print("3. Multiply")
    print("4. Divide")

    while True:
        try:
            choice = int(input("Enter choice (1/2/3/4): "))
            if choice == 0:
                print("Exiting...")
                break
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))

            if choice == 1:
                print(f"{num1} + {num2} = {add(num1, num2)}")
            elif choice == 2:
                print(f"{num1} - {num2} = {subtract(num1, num2)}")
            elif choice == 3:
                print(f"{num1} * {num2} = {multiply(num1, num2)}")
            elif choice == 4:
                result = divide(num1, num2)
                print(f"{num1} / {num2} = {result}")

        except ValueError:
            print("Invalid input. Please enter a valid number.")
        except Exception as e:
            print(f"An error occurred: {e}")

if __name__ == "__main__":
    calculator()
```

**Explanation:**
- **Modular Design:** The program uses functions for each operation, improving readability and reusability.
- **User-Friendly Interface:** Clear menu options and error handling for invalid inputs.
- **Safety:** Checks for division by zero and invalid inputs.
- **Efficiency:** Uses `try-except` for robust error handling.
- **Flexibility:** Allows for easy addition of new operations in the future.
